const Styles = {
    Alert: {
        error: {
            color: 'red',
            fontWeight: 'bold',
        },
        warning: {
            color: '#f80',
            fontWeight: 'bold',
        },
        info: {
            color: 'black',
        },
    },
    Darken: {
        position: 'fixed',
        top: 0,
        left: 0,
        opacity: 0.5,
        backgroundColor: '#000',
        width: '100vw',
        height: '100vh',
        zIndex: 150,
        webkitBackdropFilter: 'blur(2px)',
        backdropFilter: 'blur(2px)',
    },
    DialogOuter: {
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        zIndex: 150,
        alignItems: 'center',
        display: 'flex',
        justifyContent: 'center',
        padding: '16px',
        boxSizing: 'border-box',
    },
    DialogInner: {
        position: 'relative',
        color: '#222',
        backgroundColor: '#fff',
        padding: '24px',
        marginBottom: '2em',
        maxWidth: '400px',
        width: '100%',
        maxHeight: '90%',
        overflowY: 'auto',
        border: '3px solid #3d3d5d',
        borderRadius: '8px',
        boxShadow: '0 0 80px 10px #666',
        fontFamily: 'sans-serif',
        boxSizing: 'border-box',
    },
    Input: {
        height: '35px',
        width: '100%',
        maxWidth: '100%',
        borderColor: '#ccf4',
        outline: 'none',
        fontSize: '16px',
        padding: '8px',
        boxSizing: 'border-box',
        backgroundColor: '#f9f9f9',
        borderRadius: '4px',
        border: '1px solid #ccc',
        marginTop: '6px',
        fontFamily: 'inherit',
    },
    Button: {
        padding: '10px 20px',
        margin: '0 4px',
        border: '1px solid #d1d5db',
        borderRadius: '6px',
        backgroundColor: '#ffffff',
        cursor: 'pointer',
        fontSize: '14px',
        fontWeight: '500',
        color: '#374151',
        transition: 'all 0.2s ease',
    },
    PrimaryButton: {
        padding: '10px 20px',
        margin: '0 4px',
        border: '1px solid #3b82f6',
        borderRadius: '6px',
        backgroundColor: '#3b82f6',
        color: 'white',
        cursor: 'pointer',
        fontSize: '14px',
        fontWeight: '500',
        transition: 'all 0.2s ease',
    },
    ButtonsDiv: {
        display: 'flex',
        justifyContent: 'flex-end',
        gap: '12px',
        marginTop: '24px',
        paddingTop: '20px',
    },
    Label: {
        display: 'block',
        marginBottom: '12px',
        fontSize: '14px',
        fontWeight: '500',
        color: '#333',
    },
    WindowHeader: {
        margin: '0 0 20px 0',
        fontSize: '18px',
        fontWeight: '600',
        color: '#333',
        borderBottom: '1px solid #eee',
        paddingBottom: '10px',
    },
    // OAuth Provider Button Styles
    ProviderButton: {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        width: '100%',
        padding: '12px 16px',
        marginBottom: '10px',
        border: '1px solid #d1d5db',
        borderRadius: '6px',
        backgroundColor: '#ffffff',
        cursor: 'pointer',
        fontSize: '14px',
        fontWeight: '500',
        color: '#374151',
        transition: 'all 0.2s ease',
        gap: '12px',
    },
    ProviderButtonIcon: {
        width: '20px',
        height: '20px',
        flexShrink: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
    },
    ProviderButtonText: {
        flex: 1,
        textAlign: 'left',
    },
    // Provider-specific colors
    ProviderGoogle: {
        backgroundColor: '#ffffff',
        border: '1px solid #dadce0',
        color: '#3c4043',
    },
    ProviderGitHub: {
        backgroundColor: '#ffffff',
        border: '1px solid #dadce0',
        color: '#181717',
    },
    ProviderMicrosoft: {
        backgroundColor: '#ffffff',
        border: '1px solid #dadce0',
        color: '#5e5e5e',
    },
    ProviderApple: {
        backgroundColor: '#000000',
        border: '1px solid #000000',
        color: '#ffffff',
    },
    ProviderCustom: {
        backgroundColor: '#ffffff',
        border: '1px solid #dadce0',
        color: '#181717',
    },
    // Divider styles
    Divider: {
        display: 'flex',
        alignItems: 'center',
        margin: '20px 0',
        color: '#6b7280',
        fontSize: '13px',
    },
    DividerLine: {
        flex: 1,
        height: '1px',
        backgroundColor: '#e5e7eb',
    },
    DividerText: {
        padding: '0 12px',
        color: '#9ca3af',
    },
    // OTP Button (Continue with email)
    OtpButton: {
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        width: '100%',
        padding: '12px 16px',
        border: '1px solid #d1d5db',
        borderRadius: '6px',
        backgroundColor: '#f9fafb',
        cursor: 'pointer',
        fontSize: '14px',
        fontWeight: '500',
        color: '#374151',
        transition: 'all 0.2s ease',
        gap: '12px',
    },
    // Copy button for alerts with copyText
    CopyButton: {
        display: 'inline-flex',
        alignItems: 'center',
        gap: '4px',
        padding: '4px 10px',
        marginTop: '8px',
        border: '1px solid #d1d5db',
        borderRadius: '4px',
        backgroundColor: '#f9fafb',
        cursor: 'pointer',
        fontSize: '12px',
        fontWeight: '500',
        color: '#374151',
        transition: 'all 0.15s ease',
        fontFamily: 'monospace',
    },
    CopyButtonCopied: {
        display: 'inline-flex',
        alignItems: 'center',
        gap: '4px',
        padding: '4px 10px',
        marginTop: '8px',
        border: '1px solid #22c55e',
        borderRadius: '4px',
        backgroundColor: '#f0fdf4',
        cursor: 'default',
        fontSize: '12px',
        fontWeight: '500',
        color: '#16a34a',
        fontFamily: 'monospace',
    }};

